(()=>{'use strict';const $=id=>document.getElementById(id),esc=escapeHtml;
const panel=document.createElement('article');panel.className='agent-workspace';panel.id='applicationAgentV2';panel.innerHTML=`<div class="agent-intro"><div><span class="eyebrow">YOUR APPLICATION WORKFLOW</span><h2>Move from prepared to applied.</h2><p>Review a packet, choose your limits, and follow its progress.</p></div><button class="btn" type="button" id="autofillSetup">Set up autofill ↗</button></div>
<div class="product-tabs" role="tablist" aria-label="Agent workspace"><button class="btn tertiary" role="tab" id="agentTabQueue" data-agent-tab="queue" aria-controls="agentSectionQueue" aria-selected="true">Application queue</button><button class="btn tertiary" role="tab" id="agentTabRules" data-agent-tab="rules" aria-controls="agentSectionRules" aria-selected="false" tabindex="-1">Submission rules</button><button class="btn tertiary" role="tab" id="agentTabSearch" data-agent-tab="search" aria-controls="agentSectionSearch" aria-selected="false" tabindex="-1">Search & preparation</button></div>
<div class="agent-statusbar"><p role="status" aria-live="polite" id="agentV2Status">Sign in to load your application agent.</p><button class="btn tertiary" type="button" id="agentV2Refresh">Refresh</button></div>
<section id="agentSectionQueue" role="tabpanel" aria-labelledby="agentTabQueue"><div class="agent-queue-layout"><article class="card"><span class="eyebrow">NEXT APPLICATION</span><h3>Review, then queue</h3><p class="meta">Use the exact documents and answers you have checked.</p><label for="agentV2Packet">Prepared application</label><select id="agentV2Packet"><option value="">Sign in to load applications</option></select><button class="btn" id="agentV2Review" type="button">Review documents & answers</button><label class="consent-row"><input id="agentV2Approved" type="checkbox"><span>I reviewed this packet and approve its exact documents and answers.</span></label><button class="btn primary" type="button" id="agentV2Queue">Queue application</button></article><aside class="card workflow-guide"><h3>You're in control.</h3><ol><li><strong>Prepare</strong><span>Confirm your profile and tailor your documents.</span></li><li><strong>Review</strong><span>Check each packet before sending it to the agent.</span></li><li><strong>Track</strong><span>Submission appears only with employer confirmation.</span></li></ol><p class="meta">Login, security checks, declarations and missing answers need you.</p><button class="btn" type="button" data-agent-open-rules>Manage submission rules</button><button class="btn tertiary" type="button" id="agentV2Pause">Pause queued work</button></aside></div><section id="agentV2Runs" class="agent-run-list" aria-live="polite"></section></section>
<section id="agentSectionRules" role="tabpanel" aria-labelledby="agentTabRules" hidden><form id="agentV2Form" class="card"><h3>Submission rules</h3><p class="meta">These rules apply to the background application queue.</p><div class="form-grid"><div><label for="agentV2Mode">Application mode</label><select id="agentV2Mode"><option value="review">Prepare for review</option><option value="auto">Auto-apply approved packets</option></select></div><div><label for="agentV2Limit">Daily submission limit</label><input id="agentV2Limit" type="number" min="1" max="25" value="5" required></div><div><label for="agentV2Match">Minimum verified match (%)</label><input id="agentV2Match" type="number" min="50" max="100" value="85" required></div><div><label for="agentV2Countries">Countries (optional)</label><input id="agentV2Countries" placeholder="Canada, Germany, United States"><p class="meta">Comma separated. Leave blank for worldwide preferences.</p></div></div><details class="form-details"><summary>Employer exclusions</summary><label for="agentV2Exclude">Excluded employers</label><input id="agentV2Exclude" placeholder="Company names, comma separated"></details><fieldset class="consent-fieldset"><legend>Background processing</legend><label class="consent-row"><input id="agentV2Enabled" type="checkbox"><span>Enable background processing</span></label><label class="consent-row"><input id="agentV2Consent" type="checkbox"><span>I authorise submission of the packets I approve, within these limits.</span></label><p class="meta">Pausing cancels queued work. A run that has already started may finish.</p></fieldset><div class="form-footer"><button class="btn primary" type="submit">Save submission rules</button></div></form><details class="form-details"><summary>Browser connection check</summary><p class="meta">Run a neutral test form to check the cloud browser connection.</p><button class="btn" type="button" id="agentV2Test">Test browser runner</button></details></section>
<section id="agentSectionSearch" role="tabpanel" aria-labelledby="agentTabSearch" hidden><p class="meta">Search and preparation use your confirmed profile. Submission follows the separate rules above.</p><div id="agentSearchWorkspace"></div></section>
`;
$('view-agent').prepend(panel);$('autofillSetup').onclick=()=>{showView('settings');document.querySelector('[data-setting=connections]')?.click();document.getElementById('clipperId')?.scrollIntoView({block:'center'});};
const clip=$('clipperId')?.closest('article');if(clip){clip.querySelector('h2').textContent='Autofill browser extension';clip.querySelector('p').textContent='Extract the downloaded ZIP. In chrome://extensions or edge://extensions, enable Developer mode, choose Load unpacked and select the extracted folder. Copy its extension ID below, connect your signed-in account and confirm it in the extension popup. Then open an employer application form and click Autofill from the browser extension.';$('connectClipper').textContent='Connect autofill extension';clip.querySelector('a[download]').textContent='Download autofill extension';}
let settings=null,apps=[],owner=null,requestVersion=0,rulesDirty=false;
$('agentV2Form').addEventListener('input',()=>{rulesDirty=true;});
function tab(name){document.querySelectorAll('[data-agent-tab]').forEach(b=>{const selected=b.dataset.agentTab===name;b.setAttribute('aria-selected',String(selected));b.tabIndex=selected?0:-1;$(b.getAttribute('aria-controls')).hidden=!selected;});}
panel.addEventListener('click',e=>{const b=e.target.closest('[data-agent-tab],[data-agent-open-rules]');if(b)tab(b.dataset.agentTab||'rules');});
const searchWorkspace=$('agentSearchWorkspace');[...$('view-agent').children].filter(n=>n!==panel).forEach(n=>searchWorkspace.append(n));
const legacyModes=$('productAgentModes')?.closest('section');if(legacyModes)legacyModes.hidden=true;
['startAgent','pauseAgent','stopAutopilot'].forEach(id=>{if($(id))$(id).hidden=true;});
$('applicationRules').querySelector('h3').textContent='Search preferences';
$('productAgentActions').before(Object.assign(document.createElement('p'),{className:'meta',textContent:'Save your search preferences, then find opportunities. The cloud queue manages submission separately.'}));

async function call(action,body={}){const {data,error}=await supabaseClient.functions.invoke('applyflow-application-agent',{body:{action,...body}});if(error){let message=error.message;try{message=(await error.context.json()).error||message;}catch{}throw new Error(message);}if(data?.error)throw new Error(data.error);return data;}
const list=id=>$(id).value.split(',').map(x=>x.trim()).filter(Boolean);
function form(){return {mode:$('agentV2Mode').value,enabled:$('agentV2Enabled').checked,daily_limit:Number($('agentV2Limit').value),minimum_match:Number($('agentV2Match').value),countries:list('agentV2Countries'),excluded_companies:list('agentV2Exclude'),consent:$('agentV2Consent').checked};}
async function refresh(){const version=++requestVersion;const user=(await supabaseClient.auth.getUser()).data.user;if(version!==requestVersion)return;if(!user){owner=null;settings=null;apps=[];$('agentV2Packet').innerHTML='<option value="">Sign in first</option>';$('agentV2Runs').replaceChildren();$('agentV2Consent').checked=false;$('agentV2Status').textContent='Sign in to use autofill and your private application queue.';return;}owner=user.id;const expected=owner;const [data,applications]=await Promise.all([call('STATUS'),supabaseClient.from('applications').select('id,job_id,status,preparation_state,job_snapshot').eq('user_id',owner).is('applied_at',null).order('created_at',{ascending:false}).limit(100)]);if(owner!==expected||version!==requestVersion)return;if(applications.error)throw applications.error;settings=data.settings;apps=applications.data||[];for(const r of data.runs||[]){if(r.status!=='SUBMITTED'||!r.result?.confirmation_text)continue;const job=(state.jobs||[]).find(j=>j.application_id===r.application_id);if(job){job.stage='Applied';job.appliedAt=r.updated_at;job.evidence={text:r.result.confirmation_text,url:r.result.confirmation_url||r.result.current_url,ref:r.result.confirmation_id,timestamp:r.updated_at};}}renderKanban();renderHome();const s=settings;if(!rulesDirty){$('agentV2Mode').value=s.mode;$('agentV2Enabled').checked=s.enabled;$('agentV2Limit').value=s.daily_limit;$('agentV2Match').value=s.minimum_match;$('agentV2Countries').value=s.countries.join(', ');$('agentV2Exclude').value=s.excluded_companies.join(', ');$('agentV2Consent').checked=!!s.consent_at;}const selection=$('agentV2Packet').value;$('agentV2Packet').innerHTML='<option value="">Select a prepared application</option>'+apps.map(a=>`<option value="${esc(a.id)}">${esc(a.job_snapshot?.job_title||a.job_snapshot?.title||'Application')} · ${esc(a.job_snapshot?.company||'Employer')} · ${esc(a.preparation_state||'Not prepared')}</option>`).join('');if(apps.some(a=>a.id===selection))$('agentV2Packet').value=selection;$('agentV2Status').textContent=data.provider_health?.runnable===false?data.provider_health.message:data.provider_configured?(s.enabled?'Background processing enabled.':'Application agent paused.'):'Browser provider needs configuration. Autofill remains available.';$('agentV2Status').dataset.tone=data.provider_health?.runnable===false?'warning':'';$('agentV2Runs').innerHTML='<h3>Application activity</h3>'+((data.runs||[]).map(r=>{const app=apps.find(a=>a.id===r.application_id);return `<article class="card"><strong>${esc(app?.job_snapshot?.job_title||app?.job_snapshot?.title||'Application')}</strong><span class="status-badge">${esc(r.status.replaceAll('_',' '))}</span><p>${esc(r.reason||'Waiting for background processing')}</p><time class="meta">${esc(new Date(r.created_at).toLocaleString())}</time></article>`;}).join('')||'<p class="meta">No queued applications yet.</p>');}
async function busy(button,work){if(button.disabled)return;button.disabled=true;button.setAttribute('aria-busy','true');try{await work();}catch(e){$('agentV2Status').textContent=e.message;}finally{button.disabled=false;button.removeAttribute('aria-busy');}}
$('agentV2Form').onsubmit=e=>{e.preventDefault();busy(e.submitter||$('agentV2Form').querySelector('[type=submit]'),async()=>{await call('SETTINGS',form());rulesDirty=false;await refresh();});};
$('agentV2Pause').onclick=e=>busy(e.target,async()=>{const s=form();s.enabled=false;await call('SETTINGS',s);rulesDirty=false;await refresh();});
$('agentV2Refresh').onclick=e=>busy(e.target,refresh);$('agentV2Test').onclick=e=>busy(e.target,async()=>{const r=await call('TEST');await refresh();$('agentV2Status').textContent=r.message;});
$('agentV2Packet').onchange=()=>{$('agentV2Approved').checked=false;};
$('agentV2Review').onclick=()=>{const app=apps.find(a=>a.id===$('agentV2Packet').value);const job=(state.jobs||[]).find(j=>String(j.db_job_id||j.job_id||j.id)===app?.job_id);if(!job){$('agentV2Status').textContent='Open Applications and review this packet before approving it.';showView('pipeline');return;}const button=document.querySelector('[data-inspect="'+CSS.escape(String(job.job_id||job.id))+'"]');if(button)button.click();else{showView('pipeline');$('agentV2Status').textContent='Select the application in Applications to review its documents and answers.';}};
$('agentV2Queue').onclick=e=>busy(e.target,async()=>{if(rulesDirty)throw new Error('Save your updated submission rules before queuing.');if(!settings)throw new Error('Sign in and save your application rules first.');if(!settings.enabled)throw new Error('Enable background processing and save your rules first.');const id=$('agentV2Packet').value;if(!id)throw new Error('Choose an application packet.');await call('QUEUE',{application_id:id,allow_submit:settings.mode==='auto',packet_approved:$('agentV2Approved').checked});$('agentV2Approved').checked=false;await refresh();$('agentV2Status').textContent='Queued. Background processing checks the queue every minute.';});
supabaseClient.auth.onAuthStateChange(()=>{++requestVersion;owner=null;settings=null;rulesDirty=false;apps=[];$('agentV2Runs').replaceChildren();$('agentV2Approved').checked=false;setTimeout(()=>refresh().catch(e=>{$('agentV2Status').textContent=e.message;}),0);});
window.ApplyFlowApplicationAgent={async reviewPacket(job){await refresh();const app=apps.find(a=>a.id===job.application_id||a.job_id===String(job.db_job_id||job.job_id||job.id));if(!app)throw new Error('Save the prepared application before sending it to the queue.');showView('agent');tab('queue');$('agentV2Packet').value=app.id;$('agentV2Approved').checked=true;$('agentV2Status').textContent='Packet reviewed. Check your submission rules, then queue this application.';}};
setInterval(()=>{if(state.signedIn&&!document.hidden&&!$('view-agent').classList.contains('hidden'))refresh().catch(e=>{$('agentV2Status').textContent=e.message;});},30000);
const oldShow=showView;showView=function(v){oldShow(v);if(v==='agent')refresh().catch(e=>{$('agentV2Status').textContent=e.message;});};
})();
